import { lowPower } from "../animations/core/manager.js";
import { profile as p } from "../data/profile.js";
import { boot, scene, lazyScene } from "./shared.js";
import { icon } from "../components/icons.js";
import {
  esc,
  heading,
  profileLinks,
  interestCards,
} from "../components/utils.js";
import { pubCard } from "../components/pubCard.js";
import { init as initTimeline } from "../animations/timeline.js";
const featured = p.publications.filter((p) => p.firstAuthor);
boot(
  "home",
  `
  <section class="home-hero">
    <div class="home-copy">
      <p class="eyebrow page-kicker">${esc(p.home.eyebrow)}</p>
      <div class="hero-identity"><div class="profile-portrait motion-item"><img src="${p.photo}" alt="${esc(p.photoAlt)}" width="160" height="160" fetchpriority="high"></div><div><p class="identity-name">${esc(p.name)}</p><p class="identity-place mono">${esc(p.affiliation)}</p></div></div>
      <h1 class="hero-title">${esc(p.name.split(" ")[0])} <em>${esc(p.name.split(" ").slice(1).join(" "))}.</em></h1>
      <p class="hero-tagline" data-decode>${esc(p.tagline)}</p>
      <p class="home-intro">${esc(p.intro)}</p>
      <div class="hero-actions"><a class="button primary" href="${p.cv}" download>${icon("download")}${p.ui.cv}</a><a class="button" href="./publications.html">${p.ui.publications}</a><a class="button" href="./contact.html">${p.ui.contact}</a></div>
      <div class="hero-profiles">${profileLinks()}<a class="text-link" href="./research.html">${p.home.exploreResearch}</a></div>
    </div>
    <div class="hero-visual">${scene("metasurface", p.diagrams.metasurface.aria)}<div class="hero-figure-label mono"><p>${p.home.fieldLabel}</p><p>${p.home.fieldDetail}</p></div></div>
    <a class="hero-scroll mono" href="#directions"><span class="scroll-line" aria-hidden="true"></span>${p.home.scroll}</a>
  </section>
  <div class="metrics-wrap"><div class="container metrics">${p.metrics.map((m) => `<div class="metric"><span class="metric-value" data-count="${m.value}">${m.value}</span><span class="metric-label">${m.label}</span></div>`).join("")}</div></div>
  <section id="directions" class="section container">${heading(p.home.interestsEyebrow, p.home.interestsTitle)}<div class="interests-grid">${interestCards()}</div></section>
  <section class="section workflow-section"><div class="container">${heading(p.home.workflowEyebrow, p.home.workflowTitle)}<p class="section-intro">${p.home.workflowIntro}</p><div class="workflow" data-transmission><svg class="workflow-rail" viewBox="0 0 1000 24" preserveAspectRatio="none" aria-hidden="true"><path class="rail" d="M0 12h1000"/><path class="signal-path" d="M0 12h1000"/></svg>${p.workflow.map((stage) => `<article class="workflow-stage"><div class="workflow-icon">${icon(stage.icon)}</div><h3>${stage.title}</h3><p class="mono">${stage.detail}</p><p>${stage.description}</p></article>`).join("")}</div></div></section>
  <section class="section container">${heading(p.home.featuredEyebrow, p.home.featuredTitle, `<a class="text-link" href="./publications.html">${p.home.allPublications}</a>`)}<div class="featured-publications">${featured.map((pub, i) => pubCard(pub, i, true)).join("")}</div><p class="featured-note">${p.home.publicationNote}</p></section>
`,
);
lazyScene(
  "metasurface",
  () =>
    lowPower
      ? import("../animations/metasurfaceLite.js")
      : import("../animations/metasurface.js"),
  "metasurface",
);
initTimeline(document.querySelector("main"), {
  enabled: p.animations.timeline,
});
